def transform(grid):
    g = [row[:] for row in grid]
    H, W = len(g), len(g[0])
    from collections import Counter
    cnt = Counter(c for row in g for c in row)
    bg = cnt.most_common(1)[0][0]
    pts = [(r, c) for r in range(H) for c in range(W) if g[r][c] != bg]
    if not pts:
        return g
    r0 = min(p[0] for p in pts); r1 = max(p[0] for p in pts)
    c0 = min(p[1] for p in pts); c1 = max(p[1] for p in pts)
    gaps = []
    for c in range(c0, c1 + 1):
        for r in (r0, r1):
            if g[r][c] == bg:
                gaps.append((r, c))
    for r in range(r0, r1 + 1):
        for c in (c0, c1):
            if g[r][c] == bg:
                gaps.append((r, c))
    # dedupe corners
    gaps = list(set(gaps))
    if not gaps:
        return g
    k = len(gaps) // 2
    for r, c in gaps:
        g[r][c] = k
    return g
