def transform(grid):
    g = [row[:] for row in grid]
    H, W = len(g), len(g[0])
    from collections import Counter
    cnt = Counter(c for row in g for c in row)
    bg = cnt.most_common(1)[0][0]
    fgset = {c for row in g for c in row} - {bg}
    def col_has(c, r1, r2):
        return any(g[r][c] in fgset for r in range(r1, r2))
    def row_has(r, c1, c2):
        return any(g[r][c] in fgset for c in range(c1, c2))
    out = [row[:] for row in g]
    for r in range(H):
        for c in range(W):
            if g[r][c] == bg:
                if col_has(c, 0, r) and col_has(c, r+1, H):
                    out[r][c] = 2
                elif row_has(r, 0, c) and row_has(r, c+1, W):
                    out[r][c] = 2
    return out
